      "fullUrl": "https://example.org/fhir/Observation/observation-8",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-8",
        "status": "final",
        "code": {
          "text": "Reported symptoms associated with elevated blood pressure"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Denies chest pain, shortness of breath, palpitations, neurological symptoms, visual change, and severe headache."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-9",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-9",
        "status": "final",
        "code": {
          "text": "Reported right eye lesion and symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Yellow bump on the nasal side of the right eye, present for at least 1 year and more noticeable over the last few months. Mild intermittent irritation, especially on windy or dusty days at work. Denies significant pain, photophobia, discharge, or change in visual acuity. Patient thinks it may be related to increased blood pressure or chemicals leaking from new high-visibility work glasses. Optometrist reportedly described it 1–2 years ago as a 'sun thing' and nothing to worry about."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-10",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-10",
        "status": "final",
        "code": {
          "text": "Reported snoring and sleep-related symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Partner reports occasional snoring. No witnessed apnoeas and no marked daytime somnolence."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-11",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-11",
        "status": "final",
        "code": {
          "text": "General appearance"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Well-looking; mildly impatient and frequently on phone."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-12",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-12",
        "status": "final",
        "code": {
          "text": "Eye examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Visual acuity grossly intact; able to read phone and wall chart. Right eye: small, slightly raised yellow lesion on nasal bulbar conjunctiva adjacent to limbus, non-vascularised, with no corneal encroachment, significant injection, or tenderness. Left eye: smaller similar nasal lesion. Pupils equal and reactive; extraocular movements intact. No discharge, chemosis, or obvious pterygium."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-13",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-13",
        "status": "final",
        "code": {
          "text": "Cardiovascular examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Heart sounds dual; no murmurs, rubs, or gallops. No oedema. Peripheral pulses palpable."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-14",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-14",
        "status": "final",
        "code": {
          "text": "Respiratory examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Chest clear to auscultation bilaterally; no wheeze."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-15",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-15",
        "status": "final",
        "code": {
          "text": "Neurological examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Grossly non-focal; speech and gait normal."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-1",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-1",
        "status": "active",
        "medicationCodeableConcept": {
          "text": "Ibuprofen"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosage": [
          {
            "text": "Over-the-counter, as needed for musculoskeletal aches",
            "asNeededBoolean": true
          }
        ]
      }
    }
  ]
}
